mapper.select:
SELECT id, material_id, material_extend_id, bar_code, retail_price, effective_date, change_reason, change_source, source_bill_id, source_bill_number, create_time, create_serial, tenant_id, delete_flag FROM jsh_material_price_history WHERE delete_flag = '0'
AND effective_date >= #{beginDate,jdbcType=DATE}
AND effective_date <= #{endDate,jdbcType=DATE}
ORDER BY effective_date DESC, create_time DESC
